public class NoNetwork : DispatchProxy { public static int Calls; protected override object? Invoke(MethodInfo? method, object?[]? args) { Calls++; throw new Exception("Unexpected external API call: " + method?.Name); } }
public class TestSettings : DispatchProxy { public string? Group; protected override object? Invoke(MethodInfo? method, object?[]? args) => method?.Name switch { "get_CurrentGroupId" => Group, "get_Settings" => new AppSettings(), "GetCurrentGroupConfig" => null, _ => throw new Exception("Unexpected settings access: " + method?.Name) }; }
public sealed class FakeDiscord : HttpMessageHandler
{
 public int Posts, Gets; public string Mode = "ok"; public string? LastBody; public Uri? LastUri;
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage r, CancellationToken ct)
 {
  if (r.Method == HttpMethod.Post) { Interlocked.Increment(ref Posts); LastUri = r.RequestUri; LastBody = await r.Content!.ReadAsStringAsync(ct); if (Mode == "timeout") throw new HttpRequestException("SYNTHETIC secret must never appear in status"); if (Mode == "deleted") return new(HttpStatusCode.NotFound); if (Mode == "429") return Json(HttpStatusCode.TooManyRequests, "{\"retry_after\":300}"); if (Mode == "redirect") return new(HttpStatusCode.TemporaryRedirect) { Headers = { Location = new("https://evil.invalid/") } }; return Json(HttpStatusCode.OK, "{\"id\":\"123\"}"); }
  if (!r.RequestUri!.AbsolutePath.Contains("/messages/")) return Json(HttpStatusCode.OK, "{\"id\":\"123456789012345678\",\"channel_id\":\"111111111111111111\",\"guild_id\":\"222222222222222222\"}");
  Interlocked.Increment(ref Gets); if (Mode == "readback-fail") return new(HttpStatusCode.ServiceUnavailable);
  using var sent = JsonDocument.Parse(LastBody!); return Json(HttpStatusCode.OK, JsonSerializer.Serialize(new { id = "123", content = sent.RootElement.GetProperty("content").GetString(), channel_id = "111111111111111111", webhook_id = "123456789012345678" }));
 }
 private static HttpResponseMessage Json(HttpStatusCode status, string body) => new(status) { Content = new StringContent(body) };
}
